{
  "findings": [
    {
      "ref": "[D539]",
      "area": "contact",
      "claim": "A parent reports that children under 13 are automatically blocked from direct private chat with non-friends.",
      "stance": "mitigation",
      "quote": "Children under 13 are allowed by default to engage in public text chat with others joining the same experience (“Experience Chat”). However, they’re automatically blocked from chatting directly with specific players of that or other games on Roblox (“Experience Direct Chat” or “Whisper Chat”), unless a verified parent changes those settings."
    },
    {
      "ref": "[D539]",
      "area": "money",
      "claim": "A parent reports that Roblox offers in-app purchases using Robux, with the smallest purchase being 400 Robux for $4.99.",
      "stance": "risk",
      "quote": "The smallest amount you can purchase is 400 Robux for $4.99."
    },
    {
      "ref": "[D539]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal information for age verification and may share it with third parties.",
      "stance": "risk",
      "quote": "Users are free to opt-out of using facial age estimation if they are not comfortable, though Roblox does say that no information is saved or stored."
    },
    {
      "ref": "[D539]",
      "area": "age_gating",
      "claim": "A parent reports that users under 9 are automatically barred from accessing 'Moderate' content.",
      "stance": "mitigation",
      "quote": "Note that for users under the age of 9 are automatically barred from accessing “Moderate” content (though they can freely access content labeled as “Minimal” or “Mild”)."
    },
    {
      "ref": "[D539]",
      "area": "content",
      "claim": "A parent reports that some experiences may contain strong violence, realistic blood, romantic themes, alcohol, strong language, and gambling content, and these are labeled as 'Restricted' for 17+ users.",
      "stance": "risk",
      "quote": "These experiences are only available to 17+ users who verified their ages by completing ID verification."
    },
    {
      "ref": "[D539]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny and fines for data collection and child safety issues.",
      "stance": "risk",
      "quote": "Roblox has been fined by the FTC for collecting children’s data without parental consent and for failing to protect minors from sexual predators."
    }
  ]
}
